.catalog-sidebar {
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.25rem;
}

.catalog-sidebar h3 {
    margin: 0 0 1rem;
    font-size: 1.2rem;
    color: #333;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h4 {
    margin: 0 0 0.5rem;
    font-size: 0.9rem;
    color: #555;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.filter-hint {
    color: #999;
    font-size: 0.85rem;
    margin: 0;
}

