}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply {
    padding: 0.5rem 1rem;
    background: #3b82f6;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.btn-apply:hover {
    background: #2563eb;
}

.btn-clear {
    padding: 0.5rem 1rem;
    background: transparent;
    color: #666;
    border: 1px solid #ccc;
    border-radius: 6px;
    cursor: pointer;
}

.btn-clear:hover {
    background: #f0f0f0;
}

